		/** 
		 * Tests creating a new Building.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Building");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Building" );

			try {            
				Building entity = BuildingService.getBuildingInstance().createBuilding( generateNewEntity() );
				thePrimaryKey = entity.getBuildingId();
				LOGGER.info( "-- Successfully created a Building with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Building. 
		 */
		public Building testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Building" );

			Building entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Building with primary key" );
			msg.append( thePrimaryKey );
			
			BuildingFetchOneSummary fetchOneSummary = new BuildingFetchOneSummary( thePrimaryKey );

			try {
				entity = BuildingService.getBuildingInstance().getBuilding( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Building " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Building.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Building." );

			StringBuilder msg = new StringBuilder( "Failed to update a Building : " );        
			Building entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Building." );

				// for use later on...
				thePrimaryKey = entity.getBuildingId();

				BuildingService proxy = BuildingService.getBuildingInstance();            
				proxy.updateBuilding( entity );   

				LOGGER.info( "-- Successfully saved Building - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Building.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Building." );

			try{
			    Building entity = testRead(); 
				BuildingService.getBuildingInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Building with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Building with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Buildings.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Buildings:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Building : " );        
			List<Building> collection  = null;

			try {
				// call the static get method on the BuildingService
				collection = BuildingService.getBuildingInstance().getAllBuilding();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Building entity = null;            
					Iterator<Building> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getBuildingId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

